WITH valid AS (SELECT *, DATEDIFF(CURRENT_DATE(), last_restock) / 7 AS weeks_since_last_restock FROM inventory WHERE last_restock > DATE '2023-07-17'), deduped AS (SELECT id, quantity, last_restock FROM valid QUALIFY ROW_NUMBER() OVER (PARTITION BY store_id ORDER BY quantity DESC, id) = 1), with_windows AS (SELECT id, quantity, LAG(quantity) OVER w_grp AS prev_quantity, ROW_NUMBER() OVER w_grp AS row_seq, LAST_VALUE(quantity) IGNORE NULLS OVER (ORDER BY quantity, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_quantity FROM deduped WINDOW w_grp AS (ORDER BY last_restock, id)), cleaned AS (SELECT *, row_seq - last_known_quantity AS row_seq_minus_last_known_quantity FROM with_windows WHERE prev_quantity < 198), metrics AS (SELECT *, LEAD(prev_quantity) OVER w_recent AS next_prev_quantity, LAG(prev_quantity) OVER w_recent AS prev_prev_quantity, LEAD(row_seq_minus_last_known_quantity) OVER w_recent AS next_row_seq_minus_last_known_quantity, ROW_NUMBER() OVER w_recent AS row_seq_2 FROM cleaned WHERE row_seq_minus_last_known_quantity IS NOT NULL WINDOW w_recent AS (ORDER BY row_seq_minus_last_known_quantity, id)), metrics_inventory AS (SELECT id, quantity, row_seq, last_known_quantity, row_seq_minus_last_known_quantity, next_prev_quantity, next_row_seq_minus_last_known_quantity, ROW_NUMBER() OVER (ORDER BY row_seq_minus_last_known_quantity DESC, id) AS event_seq, FIRST_VALUE(row_seq_2) IGNORE NULLS OVER (ORDER BY row_seq_minus_last_known_quantity, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_row_seq_2, FIRST_VALUE(prev_quantity, TRUE) OVER w_running AS first_known_prev_quantity, LEAD(last_known_quantity, 1, 0) OVER (ORDER BY row_seq_2, id) AS next_last_known_quantity, SUM(row_seq_minus_last_known_quantity) OVER w_running AS running_row_seq_minus_last_known_quantity FROM metrics WINDOW w_running AS (ORDER BY last_known_quantity, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)), cleaned_inventory AS (SELECT id, quantity, row_seq, row_seq_minus_last_known_quantity, next_prev_quantity, first_known_row_seq_2, first_known_prev_quantity, next_last_known_quantity, running_row_seq_minus_last_known_quantity, CAST(next_prev_quantity AS DOUBLE) AS next_prev_quantity_num FROM metrics_inventory WHERE last_known_quantity = 177) SELECT id, quantity, row_seq_minus_last_known_quantity, first_known_row_seq_2, first_known_prev_quantity, next_last_known_quantity, running_row_seq_minus_last_known_quantity FROM cleaned_inventory
